mapper.select:
select clo.portfolio as portnum,ph.PORT_NAME as portname,clo.closeDate,clo.CUSIP as secMasterID,ii.SECURITYID as securityid, ii.issueType as issuerType,ii.securityname,isr.issuerName,clo.managerID,clo.secacct as secAcctID,sa.defaultCashAcct as defaultCashAcctID, sa.brokerCode as brokerID,ph.CURRENCYCODE as funcCurID,ii.priCur as localCurID,ii.incomeCur as incomeCurID,clo.amount, clo.gCost as cost,clo.gCostFunc as funcCost,(case when clo.altRate>0 and ii.issueType=108 then clo.amrValue else clo.GMKVALUE end) as mkValue, clo.accrued as accrued,clo.lsindicator as lsindicator,clo.amrValue as amortValue, round((case when clo.altRate>0 and ii.issueType=108 then clo.amrValue else clo.GMKVALUE end)*clo.PRINFXRATE,2) as funMkValue from tran_clo clo, portfolio_hdr ph, issue_info ii, issuer isr, secacct sa where clo.portfolio=ph.portfolio and clo.cusip=ii.cusip and ii.issuer=isr.issuerID and clo.secacct=sa.acctID and clo.portfolio in
#{item}
and clo.closedate=#{closeDate}

choose.when:
select * from Tran_Clo clo1 where clo1.id in 
(select max(clo.id) from Tran_Clo clo where clo.portfolio=#{portnum} and clo.cusip=#{cusip} 

 and clo.closeDate<=#{closeDate} 

 group by clo.lotnum)

choose.otherwise:
        	select * from Tran_Clo clo1 where clo1.id in (select max(clo.id) from Tran_Clo clo where clo.portfolio in

				#{item}


			and clo.cusip=#cusip} and clo.closeDate<=#{closeDate} group by clo.lotnum)

mapper.select:
select * from Tran_Clo clo where clo.portfolio in

	#{item}


and clo.cusip=#{cusip} and clo.closeDate<=#{closeDate} and clo.altRate!=0 order by clo.closeDate asc

choose.otherwise:
        	select * from Tran_Clo where portfolio in

				#{item}

			 and cusip=#{cusip} and closeDate=#{closeDate}
